// Next.js validates the Supabase bearer token before calling n8n. Validate the shared secret before processing.
const input = $input.first().json;
const headers = input.headers || {};
const supplied = headers['x-n8n-secret'] || headers['X-N8N-SECRET'];
if (!$env.N8N_WEBHOOK_SECRET || supplied !== $env.N8N_WEBHOOK_SECRET) throw new Error('Unauthorized webhook');
const body = input.body || {};
const user_id = String(body.user_id || '').trim();
let conversation_id = String(body.conversation_id || '').trim();
const message = String(body.message || '').trim();
const valid = /^[0-9a-f-]{36}$/i.test(user_id) && message.length > 0 && message.length <= 10000;
if (!conversation_id) conversation_id = 'conv-' + Date.now() + '-' + Math.random().toString(36).slice(2, 8);
return [{ json: { user_id, customer_id: user_id, conversation_id, message, domain: 'medical', valid } }];

// Validate/sanitize the agent output and produce a safe classification object.
const item = $input.first().json;
const vi = $('Validate Input').first().json;
const cls = item.output || null;

let intent = (cls && cls.intent) || 'Other';
let response = (cls && cls.response ? String(cls.response) : '');
let escalate = !!(cls && cls.escalate === true);
let reason = (cls && cls.escalation_reason) || null;
let errors = null;

// Agent error output (no parsed output present) -> safe escalation
if (!cls) {
  escalate = true;
  intent = 'Human support';
  reason = 'AI processing failed';
  const e = item.error;
  errors = (e && (e.message || JSON.stringify(e))) || 'agent_error';
  response = '';
}

// Security: strip any leaked secrets / prompt markers
const banned = [/sk-[A-Za-z0-9]{12,}/g, /api[_-]?key\s*[:=]\s*\S+/gi, /system prompt/gi, /BEGIN [A-Z ]*PRIVATE KEY/gi];
for (const re of banned) { response = response.replace(re, '[redacted]'); }

// Fallback when empty
if (!response || !response.trim()) {
  response = 'Sorry, I was unable to fully process your request. I am connecting you with a human support agent.';
  escalate = true;
  if (!reason) reason = 'empty_response';
}

return [{ json: {
  conversation_id: vi.conversation_id,
  customer_id: vi.customer_id,
  intent,
  response,
  escalated: escalate,
  escalation_reason: reason,
  ticket_id: null,
  errors,
} }];

// Build the final response object for storage, logging, and the webhook reply.
const rv = $('Response Validation').first().json;
let ticket_id = rv.ticket_id != null ? rv.ticket_id : null;
try {
  const t = $('Create Escalation Ticket').first().json;
  if (t && t.ticket_id != null) ticket_id = t.ticket_id;
} catch (e) { /* not escalated */ }

let response = rv.response || '';
if (rv.escalated && !/human/i.test(response)) {
  response = (response ? response + ' ' : '') + 'Your request has been forwarded to a human support agent who will follow up shortly.';
}

return [{ json: {
  conversation_id: rv.conversation_id,
  customer_id: rv.customer_id,
  intent: rv.intent,
  response,
  escalated: !!rv.escalated,
  ticket_id,
  errors: rv.errors || null,
} }];
